raw_response:
{
  "background": "（推断）来访者是一位成年人，可能处于工作或社交环境中，与家人同住或保持密切接触。",
  "self_view_of_problem": "我觉得对外人基本不会表达一点点的愤怒和委屈，怕别人承受不了，但对自己的家人又表达得太过了。在我看来，和别人生气是很大的事，从没觉得愤怒有程度之分。",
  "resistance_drivers": [
    "当咨询师将情绪表达（如撒娇）正常化或视为可练习的技能时，来访者以沉默（如“嗯”）或强调愤怒的严重性（“在我看来愤怒就是很大的事”）来保持距离，暗示其根深蒂固的‘情绪表达是大事’的信念。",
    "（推断）当咨询师试图引导来访者看到情绪积累的后果（如火山爆发）时，来访者可能通过简短的附和（“嗯”）来回避深入探讨自己情绪压抑的具体模式。"
  ],
  "ambivalence": {
    "for_change": "（推断）来访者内心渴望能更自如地表达情绪，尤其是对外人表达一点点的愤怒和委屈，以避免情绪过度压抑或最终对家人爆发。",
    "against_change": "（推断）来访者内心依恋于将愤怒视为‘很大的事’的认知框架，这为其长期的情绪压抑提供了合理化和安全感，改变意味着要面对表达情绪可能带来的失控感和对他人造成伤害的恐惧。"
  },
  "values_and_stakes": [
    "（推断）改变可能意味着失去与家人关系中现有的、尽管可能过度的情绪表达模式，这种模式可能构成了某种熟悉的互动纽带。",
    "（推断）改变可能意味着失去‘怕别人承受不了’所维护的、对外人际关系中‘体贴、无害’的自我形象或角色。"
  ],
  "key_facts": [
    "来访者对外人基本不会表达一点点的愤怒和委屈。",
    "来访者对自己的家人会表达过度的情绪。",
    "来访者认为和别人生气是很大的事，从没想过愤怒可以有程度之分。"
  ]
}

{
  "background": "（推断）来访者可能从事或接触过人工智能、对话系统或客服相关领域的工作，对AI对话逻辑和话术有直接经验。",
  "self_view_of_problem": "（推断）来访者认为当前咨询对话效率低下，咨询师的回应方式像AI的兜底话术，无法有效引导多轮深入对话，导致沟通受阻。",
  "resistance_drivers": [
    "当咨询师尝试理解或定义来访者使用的概念（如‘奔放’）时，来访者会通过将咨询师比作AI、批评其话术生硬和效率低下来表达阻抗，实质是质疑咨询方法的有效性。"
  ],
  "ambivalence": {
    "for_change": "（推断）来访者渴望一种更高效、更有深度、能引导多轮对话的沟通方式来解决自己的问题。",
    "against_change": "（推断）来访者对当前咨询互动模式感到失望和防御，可能隐含对投入信任后再次遭遇无效沟通的抗拒。"
  },
  "values_and_stakes": [
    "（推断）改变可能意味着来访者需要放弃自己作为对话系统内行人的评判视角和对效率的掌控感。"
  ],
  "key_facts": [
    "来访者曾参与过天猫精灵的答复相关工作或项目。",
    "来访者明确指出了当前对话效率很低。",
    "来访者将咨询师的大部分话术类比为AI的兜底话术。"
  ]
}

{
  "background": "（推断）来访者是一位成年人，可能处于工作或家庭压力较大的生活阶段，近期经历了需要长时间恢复的困难事件。",
  "self_view_of_problem": "我觉得自己缓了两个月了，但改变的时间太长，让我心力交瘁，想快点回到之前有能量、自信的状态。",
  "resistance_drivers": [
    "当咨询师将问题归因于‘最近发生太多事，让你有些累了’并建议‘放松下来等一等’时，来访者通过强调‘我都缓了两个月了’来反驳，表现出对咨询师将问题最小化或建议被动等待的不耐烦和阻抗。",
    "（推断）当咨询师未能立即回应时（‘你还在吗’），来访者表现出对咨询师关注度或连接中断的敏感和焦虑，这可能激活其寻求即时确认的阻抗模式。"
  ],
  "ambivalence": {
    "for_change": "（推断）来访者渴望摆脱心力交瘁的状态，重新获得自信和活力，推动其寻求改变。",
    "against_change": "（推断）来访者可能对‘放松等待’的被动状态存在某种情感依恋或惯性，因为快速改变本身也意味着要面对新的不确定性和消耗。"
  },
  "values_and_stakes": [
    "（推断）改变（如不再被动等待）可能意味着失去目前被允许的‘缓冲期’或休息的正当性，以及由此带来的他人（如母亲）的照顾或支持。",
    "（推断）快速回到之前状态可能面临失败的风险，从而失去对自己‘有力量’这一积极身份的认同。"
  ],
  "key_facts": [
    "来访者已经为当前问题‘缓了两个月’。",
    "来访者在对话中曾向母亲表达力量并感到自信。",
    "来访者在咨询师短暂未回应时发出了‘你还在吗’的询问。"
  ]
}

{
  "background": "（推断）来访者是一名在国内工作的职场人士，目前可能处于居家办公或隔离状态，工作环境受疫情影响存在不确定性。",
  "self_view_of_problem": "在家没什么氛围，效率低，还不如不工作，发发呆都是好的；工作要有产出，只是走形式，没有意义，浪费时间。",
  "resistance_drivers": [
    "当咨询师将问题归因于外部共识（如'既然大家都这么认为，我又何必认真工作呢？'）时，来访者会立即反驳，并强调问题核心在于自身对在家工作环境效率低下的感受。",
    "（推断）当咨询师将来访者的行为解读为对'结果'的注重或'不能接受自己效率低的状态'时，可能激活阻抗，表现为来访者转而强调在家进行其他休闲活动（睡觉、打游戏等）的积极价值，以此合理化或转移对工作问题的讨论。"
  ],
  "ambivalence": {
    "for_change": "（推断）来访者内心可能承认或渴望一种更有意义、有产出的工作状态，而非仅仅是走形式。",
    "against_change": "（推断）来访者情感上依恋或认同于在家时放松、休闲（如睡觉、打游戏、看电影、看书）所带来的舒适和自由感，将其视为比低效工作更好的选择。"
  },
  "values_and_stakes": [
    "（推断）改变（即在家认真工作）可能意味着失去在家环境中自由安排时间、进行个人休闲活动（睡觉、打游戏、看电影、看书）的舒适和自主权。",
    "（推断）改变可能破坏来访者目前对'工作要有产出，只是走形式没有意义'这一认知所维持的心理平衡，迫使ta面对在家工作也可能需要高效产出的压力。"
  ],
  "key_facts": [
    "来访者认为在家工作没什么氛围，效率低。",
    "来访者觉得在家睡觉、打游戏、看电影、看书都比工作好很多。",
    "来访者提到'主要不知道要封几天 硬要跑回[国内地点]也能跑'，表明其工作地点和状态受疫情封控影响，存在返回特定地点的可能性。"
  ]
}

{
  "background": "（推断）来访者从事与医学相关的工作，可能是一名医生或医学研究者，对跨学科研究感兴趣。",
  "self_view_of_problem": "（推断）来访者认为自己的问题在于对医学的感觉很微妙，不确定潜意识是否在帮助自己做选择，对当前经历的意义感到困惑。",
  "resistance_drivers": [
    "当咨询师提出‘潜意识一直照顾着自己’这类赋予积极意义的解读时，来访者以‘是这样的吗’的疑问表现出轻微的质疑和不确定，阻抗表现为对咨询师观点的被动接受而非深入探索。",
    "（推断）当咨询师将当前经历解释为‘生命需要的课程’时，来访者以‘或许是的’这种模糊、保留的附和回应，阻抗表现为避免深入讨论自身感受，维持表面的认同。"
  ],
  "ambivalence": {
    "for_change": "（推断）来访者内心渴望理解自己‘对医学的感觉很微妙’以及潜意识是否在引导选择的困惑，希望获得清晰的意义。",
    "against_change": "（推断）来访者可能依恋于当前这种‘微妙’和不确定的状态，将其视为一种安全的、无需立刻做出明确改变或承诺的缓冲地带。"
  },
  "values_and_stakes": [
    "（推断）改变可能意味着失去目前工作中那种‘感觉微妙’所带来的灵活性和探索空间，被迫对医学或职业路径做出非此即彼的明确选择。",
    "（推断）改变可能挑战来访者对自己‘潜意识’运作方式的现有理解，失去一种神秘或不可控的自我叙事。"
  ],
  "key_facts": [
    "来访者对医学的感觉很微妙。",
    "来访者不确定自己的潜意识是否在帮助自己做选择。",
    "来访者对咨询师关于‘生命课程’的观点表示了‘或许是的’这种保留性同意。"
  ]
}

{
  "background": "（推断）来访者是一名有10年工作经验的职场人士，可能从事需要在线沟通或客户服务的行业，对心理咨询行业的工作模式有一定了解。",
  "self_view_of_problem": "来访者将自己的困境视为一个“持续太久了”的“瓶颈期”，虽然以前也有过职业困难并成功度过，但这次持续时间过长让他感到困扰。",
  "resistance_drivers": [
    "当咨询师试图聚焦于其个人状态（如询问从业时长）时，来访者会转移话题到咨询师或咨询行业本身（如询问入职方式、兼职岗位），以此回避深入探讨自身问题。",
    "（推断）当咨询师尝试共情或正常化其感受时，来访者可能用“哈哈，挺好玩儿的”这类轻松化或调侃的语气来淡化问题的严重性，保持情感距离。"
  ],
  "ambivalence": {
    "for_change": "（推断）来访者承认当前的“瓶颈期”持续时间过长，这暗示他内心存在一种对现状不满、希望有所突破或改变的渴望。",
    "against_change": "（推断）来访者将困境视为“瓶颈期”并曾通过“安慰自己”来应对，这背后可能隐藏着对改变带来的不确定性和潜在失败的恐惧，以及对“安慰自己”这种熟悉应对模式的依恋。"
  },
  "values_and_stakes": [
    "（推断）改变可能意味着失去“安慰自己”这种熟悉的、能暂时缓解焦虑的自我应对机制。",
    "（推断）改变可能威胁到来访者对自己“能度过职业困难”的既有成功认同和职业身份感。"
  ],
  "key_facts": [
    "来访者目前正经历一个持续了很长时间的职业瓶颈期。",
    "来访者在这个行业已经工作了10年。",
    "来访者曾使用过“平安医生心理科”的服务。"
  ]
}

{
  "background": "（推断）来访者是一名职场人士，工作压力大，经常加班熬夜，处于高负荷的工作状态中。",
  "self_view_of_problem": "这不是个问题，加班熬夜很正常，说了也没用，熬着就行了。",
  "resistance_drivers": [
    "当咨询师建议调整或改变时，来访者会立刻以极端化（如‘辞职吗？’）或否定（‘算了吧’）的方式反驳，表现出对改变的抗拒。",
    "（推断）当咨询师指出其疲惫状态并试图提供帮助时，来访者会以‘正常化’（‘不是很正常吗？’）和‘无用论’（‘说了也没用’）来否认问题的存在，从而回避深入探讨。"
  ],
  "ambivalence": {
    "for_change": "（推断）内心可能承认这种疲惫状态是不舒服的，并隐约希望有所缓解。",
    "against_change": "（推断）内心对‘熬着’的现状有一种习惯性的依赖或认同，认为改变是徒劳且充满风险的。"
  },
  "values_and_stakes": [
    "（推断）改变可能会失去目前的工作岗位或稳定的收入来源。",
    "（推断）改变可能会破坏其‘能吃苦’、‘扛得住’的自我形象或职业认同。"
  ],
  "key_facts": [
    "来访者认为加班熬夜是正常现象。",
    "来访者认为谈论压力或寻求改变是没用的。",
    "来访者目前的选择是继续‘熬着’现状。"
  ]
}

{
  "background": "（推断）来访者是一位成年人，与父母同住或关系密切，可能处于需要承担更多家庭责任的阶段。",
  "self_view_of_problem": "（推断）来访者认为自己难以向父母表达内心的感受，尤其是在面对父母老去和家庭责任时，感到行动上有困难。",
  "resistance_drivers": [
    "当咨询师提出具体行动建议（如向父母表达感受）时，来访者会以‘感觉会有点困难’来委婉表达阻抗，而不是直接拒绝。"
  ],
  "ambivalence": {
    "for_change": "（推断）来访者内心承认向父母表达感受可能是一种让父母减少操心、体现自己长大的方式。",
    "against_change": "（推断）来访者对改变（即表达感受）怀有情感上的畏难和不适，可能源于习惯的互动模式或对暴露脆弱的不安。"
  },
  "values_and_stakes": [
    "（推断）改变（主动表达感受）可能会失去与父母之间现有的、熟悉的互动模式和情感距离。"
  ],
  "key_facts": [
    "来访者在咨询快结束时会有一种未具体说明的‘感觉’。",
    "咨询中曾提到父亲就医的事情让来访者感受到父母的老去。",
    "来访者之前咨询中提到了自己想为家人做一些事情的感受。"
  ]
}

{
  "background": "（推断）来访者是一名在职人员，有科长和同事，工作单位存在招人困难的情况。",
  "self_view_of_problem": "（推断）来访者认为自己现在因为工作失眠，天天没精打采，不愿意跟别人聊天，并且在工作上感到困难，产生了自我精神内耗和焦虑。",
  "resistance_drivers": [
    "当咨询师或他人指出其潜在优势或能力时，来访者会立刻用具体事例（如轮滑放弃、摄影没天赋、数学只是课本水平）来反驳或否定，表现出对积极评价的阻抗。",
    "（推断）当面对工作任务的客观评价（如同事认为不难）时，来访者会强调自己的主观困难（‘我不会’）和负面情绪（内耗、焦虑），以此作为维持现状的理由。"
  ],
  "ambivalence": {
    "for_change": "（推断）来访者渴望摆脱因工作导致的失眠、无精打采和社交回避的现状。",
    "against_change": "（推断）来访者内心可能依恋于一种‘我不行’或‘我能力不足’的自我认同，改变这种认同会带来威胁。"
  },
  "values_and_stakes": [
    "（推断）改变后可能失去‘在单位里因招不到人而获得的特殊关照或容忍’（如科长的鼓励）。",
    "（推断）改变后可能失去目前‘通过自我否定和焦虑来回避社交与深入工作挑战’的心理舒适区。"
  ],
  "key_facts": [
    "来访者提到轮滑突然放下了就没再去练习。",
    "来访者提到摄影老师曾说他比较适合人文，因为那会儿比较社牛外向乐观。",
    "来访者提到单位同事说工作不难，大专生高中生都可以，但来访者觉得好难，不会。"
  ]
}

{
  "background": "（推断）来访者是一位有职业经历、可能已为人父母的成年人，近期经历了跳槽等人生转折，正在为未来奋斗。",
  "self_view_of_problem": "（推断）来访者认为自己的人生经历丰富但充满转折和辛苦，可能不确定自己的奋斗方向或问题所在，急切希望从外部获得对自身问题的明确界定。",
  "resistance_drivers": [
    "当咨询师的回应偏向于肯定或总结（如'丰富的人生经历'、'努力奋斗'）而非直接指出问题时，来访者会表现出不耐烦并催促对方'直说'。",
    "（推断）当咨询师未能直接回应其'我的问题是什么'的核心询问时，来访者可能表现出对模糊回应的抗拒，要求得到明确的问题诊断。"
  ],
  "ambivalence": {
    "for_change": "（推断）来访者渴望通过明确自身问题来获得清晰的方向，以改善现状或未来。",
    "against_change": "（推断）来访者可能对直面自身问题的核心或潜在负面评价感到不安，这阻碍其深入自我探索。"
  },
  "values_and_stakes": [
    "（推断）改变（即明确问题）可能失去当前对自身'努力奋斗'形象的认同或掌控感。",
    "（推断）改变可能破坏其基于过往选择（如为家庭跳槽）所建立的生活叙事稳定性。"
  ],
  "key_facts": [
    "来访者近期为了孩子的未来选择了跳槽。",
    "来访者主动要求咨询师'直说'自己的看法。",
    "来访者直接询问'我的问题是什么？'。"
  ]
}

{
  "background": "（推断）一位经历过创伤性事件（可能涉及手术）的来访者，目前正在接受心理咨询。",
  "self_view_of_problem": "（推断）来访者认为自己的问题源于自卑，而不是创伤后的普遍反应。",
  "resistance_drivers": [
    "当咨询师将来访者的感受普遍化或归因于创伤时，来访者会提出质疑或转移话题，例如询问‘创伤以后都会想要去掩饰创伤吗？’来挑战咨询师的解释。",
    "（推断）当咨询师试图深入探讨感受（如‘你是说手术之后的，感受嘛？还是一直存在的感受’）时，来访者可能通过宣布‘时间到了’来中断对话，避免深入讨论。"
